const body = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};
const authHeader = headers.authorization || '';

const rawDate = (body.leave_date || body.leaveDate || '').trim();
const rawEndDate = body.end_date || body.endDate || '';
const fmt = (d) => {
  if (!d) return '';
  const pd = new Date(d);
  if (isNaN(pd)) return d;
  return pd.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

return [{ json: {
  token: authHeader.replace('Bearer ', ''),
  leaveId: body.leaveId || body._id || '',
  leave_date: rawDate,
  end_date: rawEndDate,
  leaveDateDisplay: fmt(rawDate),
  endDateDisplay: fmt(rawEndDate),
  leave_days: parseInt(body.leave_days || body.leaveDays || 1),
  reason: body.reason || '',
  employee_email: body.employee_email || body.employeeEmail || '',
  employee_name: body.employee_name || body.employeeName || '',
  department: body.department || '',
  managerEmail: body.managerEmail || '',
  hrEmail: body.hrEmail || '',
  managerApprovalToken: body.managerApprovalToken || '',
  hrApprovalToken: body.hrApprovalToken || '',
  backendUrl: 'http://backend:3001/api' 
} }];

