const llmOutput = $input.first().json;
const content = llmOutput.text || llmOutput.message || llmOutput.response || JSON.stringify(llmOutput);

let decision = 'approve';
let reason = 'Khong the phan tich AI response. Mac dinh duyet vi la nghi 1 ngay.';

try {
  const jsonMatch = content.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    decision = (parsed.decision || 'approve').toLowerCase().trim();
    reason = parsed.reason || 'Khong co ly do';
  }
} catch (e) {}

const input = $('Parse Input').first().json;
return [{ json: {
  decision,
  reason,
  rawResponse: content,
  leaveId: input.leaveId,
  leave_date: input.leave_date,
  leaveDateDisplay: input.leaveDateDisplay,
  end_date: input.end_date,
